from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Remove any spaces from the input string
    separate_groups = []  # Initialize an empty list to store the separate groups
    current_group = ""
    open_braces = 0

    for char in paren_string:
        if char == "(":
            open_braces += 1
        elif char == ")":
            open_braces -= 1

        current_group += char

        if open_braces == 0:
            separate_groups.append(current_group)
            current_group = ""

    return separate_groups

